function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
;


dx(1)=(u(1)+ u(2)                                                                                                     )*tal;
dx(2)=(((x(3)/(14.35+x(3)+(x(3)^2/111.5))*(x(6)+x(7)*0.22/(0.22+x(5))))*x(2)-(u(1)+u(2))*x(2)/x(1))                   )*tal;
dx(3)=((u(1)/x(1)*100-(u(1)+u(2))*x(3)/x(1)-(x(3)/(14.35+x(3)+(x(3)^2/111.5))*(x(6)+x(7)*0.22/(0.22+x(5))))*x(2)/0.51))*tal;
dx(4)=(((0.233*x(3)/(14.35+x(3)+(x(3)^2/111.5))*((0.0005+x(5))/(0.022+x(5))))*x(2)-(u(1)+u(2))*x(4)/x(1))             )*tal;
dx(5)=((u(2)*4/x(1)-(u(1)+u(2))*x(5)/x(1))                                                                            )*tal;
dx(6)=((-(0.09*x(5)/(0.034+x(5)))*x(6))                                                                               )*tal;
dx(7)=(((0.09*x(5)/(0.034+x(5)))*(1-x(7)))                                                                            )*tal;
dx(8)=( u(2)                                                                                                          )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
